// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait MaterialActionArbitration_material_continuity_process_material_action_arbitration_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration)
  }

  /** helper function to set the values of all input ports.
   * @param emergency_state payload for data port emergency_state
   * @param urgent_proposal payload for data port urgent_proposal
   * @param routine_proposal payload for data port routine_proposal
   * @param replenishment_proposal payload for data port replenishment_proposal
   */
  def put_concrete_inputs(emergency_state : Factory_Material_Continuity_Coordinator.EmergencyState.Type,
                          urgent_proposal : Factory_Material_Continuity_Coordinator.ProposalState.Type,
                          routine_proposal : Factory_Material_Continuity_Coordinator.ProposalState.Type,
                          replenishment_proposal : Factory_Material_Continuity_Coordinator.ProposalState.Type): Unit = {
    put_emergency_state(emergency_state)
    put_urgent_proposal(urgent_proposal)
    put_routine_proposal(routine_proposal)
    put_replenishment_proposal(replenishment_proposal)
  }


  /** helper function to check MaterialActionArbitration_material_continuity_process_material_action_arbitration's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param decision method that will be called with the value of the outgoing data
   *        port 'decision'.
   */
  def check_concrete_output(decision: Factory_Material_Continuity_Coordinator.Decision => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val decisionValue: Factory_Material_Continuity_Coordinator.Decision = get_decision().get
    if(!decision(decisionValue)) {
      testFailures = testFailures :+ st"'decision' did not match expected: value of the outgoing data port is ${decisionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_emergency_state(value : Factory_Material_Continuity_Coordinator.EmergencyState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration.operational_api.emergency_state_Id, Factory_Material_Continuity_Coordinator.EmergencyState_Payload(value))
  }

  // setter for in DataPort
  def put_urgent_proposal(value : Factory_Material_Continuity_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration.operational_api.urgent_proposal_Id, Factory_Material_Continuity_Coordinator.ProposalState_Payload(value))
  }

  // setter for in DataPort
  def put_routine_proposal(value : Factory_Material_Continuity_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration.operational_api.routine_proposal_Id, Factory_Material_Continuity_Coordinator.ProposalState_Payload(value))
  }

  // setter for in DataPort
  def put_replenishment_proposal(value : Factory_Material_Continuity_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration.operational_api.replenishment_proposal_Id, Factory_Material_Continuity_Coordinator.ProposalState_Payload(value))
  }

  // getter for out DataPort
  def get_decision(): Option[Factory_Material_Continuity_Coordinator.Decision] = {
    val value: Option[Factory_Material_Continuity_Coordinator.Decision] = get_decision_payload() match {
      case Some(Factory_Material_Continuity_Coordinator.Decision_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port decision.  Expecting 'Factory_Material_Continuity_Coordinator.Decision_Payload' but received ${v}")
      case _ => None[Factory_Material_Continuity_Coordinator.Decision]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_decision_payload(): Option[Factory_Material_Continuity_Coordinator.Decision_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryMaterialContinuityCoordinatorSystem_Instance_material_continuity_process_material_action_arbitration.initialization_api.decision_Id).asInstanceOf[Option[Factory_Material_Continuity_Coordinator.Decision_Payload]]
  }

}
